1	/* Headerless (raw) audio, and the sample coding used by nearly every other
2	 * format module.
3	 *
4	 * Original work, written from the observed behaviour of the reference program.
5	 *
6	 * The diagnostics issued from here must appear to come from the `raw'
7	 * subsystem (the reference prints e.g. "WARN raw: `f.s16': sample rate not
8	 * specified; trying 8kHz"), so the message subsystem is set explicitly rather
9	 * than being taken from this file's name.
10	 */
11	#include "sox_i.h"
12	
13	#define RAW_SUBSYSTEM "raw.c"
14	#define raw_warn   (sox_globals.subsystem = RAW_SUBSYSTEM), lsx_warn_impl
15	#define raw_report (sox_globals.subsystem = RAW_SUBSYSTEM), lsx_report_impl
16	
17	/*--------------------------- Encoding dispatch ----------------------------*/
18	
19	typedef enum {
20	  raw_bad, raw_s8, raw_u8, raw_ulaw, raw_alaw,
21	  raw_s16, raw_u16, raw_s24, raw_u24, raw_s32, raw_u32, raw_f32, raw_f64
22	} raw_kind_t;
23	
24	static raw_kind_t raw_kind(sox_format_t ft)
25	{
26	  unsigned bits = ft->encoding.bits_per_sample;
27	
28	  switch (ft->encoding.encoding) {
29	    case SOX_ENCODING_SIGN2:
30	      return bits == 8 ? raw_s8 : bits == 16 ? raw_s16 :
31	             bits == 24 ? raw_s24 : bits == 32 ? raw_s32 : raw_bad;
32	    case SOX_ENCODING_UNSIGNED:
33	      return bits == 8 ? raw_u8 : bits == 16 ? raw_u16 :
34	             bits == 24 ? raw_u24 : bits == 32 ? raw_u32 : raw_bad;
35	    case SOX_ENCODING_ULAW:
36	      return bits == 8 ? raw_ulaw : raw_bad;
37	    case SOX_ENCODING_ALAW:
38	      return bits == 8 ? raw_alaw : raw_bad;
39	    case SOX_ENCODING_FLOAT:
40	      return bits == 32 ? raw_f32 : bits == 64 ? raw_f64 : raw_bad;
41	    default:
42	      return raw_bad;
43	  }
44	}
45	
46	static void raw_bad_size(sox_format_t ft)
47	{
48	  ft->sox_errno = SOX_EFMT;
49	  strncpy(ft->sox_errstr, "this handler does not support this data size",
50	          sizeof(ft->sox_errstr) - 1);
51	  ft->sox_errstr[sizeof(ft->sox_errstr) - 1] = '\0';
52	}
53	
54	/*----------------- Bit and nibble reversal (8-bit codings) -----------------*/
55	
56	/* The reference applies these only to codings whose unit is a single byte
57	 * (or a nibble); 16-bit and wider samples are left alone even when
58	 * `Reverse Bits' is reported as `yes'. */
59	
60	static uint8_t raw_bitrev(uint8_t b)
61	{
62	  b = (uint8_t)((b >> 4) | (b << 4));
63	  b = (uint8_t)(((b & 0xcc) >> 2) | ((b & 0x33) << 2));
64	  b = (uint8_t)(((b & 0xaa) >> 1) | ((b & 0x55) << 1));
65	  return b;
66	}
67	
68	static void raw_reverse(sox_format_t ft, uint8_t *buf, size_t n)
69	{
70	  size_t i;
71	
72	  if (ft->encoding.reverse_bits == SOX_OPTION_YES)
73	    for (i = 0; i < n; ++i)
74	      buf[i] = raw_bitrev(buf[i]);
75	  if (ft->encoding.reverse_nibbles == SOX_OPTION_YES)
76	    for (i = 0; i < n; ++i)
77	      buf[i] = (uint8_t)((buf[i] >> 4) | (buf[i] << 4));
78	}
79	
80	static size_t raw_read_bytes(sox_format_t ft, uint8_t *buf, size_t n)
81	{
82	  size_t got = lsx_readbuf(ft, buf, n);
83	  raw_reverse(ft, buf, got);
84	  return got;
85	}
86	
87	static size_t raw_write_bytes(sox_format_t ft, uint8_t *buf, size_t n)
88	{
89	  raw_reverse(ft, buf, n);
90	  return lsx_writebuf(ft, buf, n);
91	}
92	
93	/*-------------------------------- Reading ---------------------------------*/
94	
95	#define RAW_BLOCK 1024
96	
97	typedef union {
98	  uint8_t  b[RAW_BLOCK];
99	  uint16_t w[RAW_BLOCK];
100	  uint32_t dw[RAW_BLOCK];
101	  float    f[RAW_BLOCK];
102	  double   d[RAW_BLOCK];
103	} raw_block_t;
104	
105	#define RAW_READ_LOOP(read_n, conv) do { \
106	    got = read_n; \
107	    for (i = 0; i < got; ++i) \
108	      buf[i] = conv; \
109	  } while (0)
110	
111	size_t lsx_rawread(sox_format_t ft, sox_sample_t *buf, size_t len)
112	{
113	  raw_kind_t kind = raw_kind(ft);
114	  size_t done = 0;
115	  raw_block_t t;
116	
117	  if (kind == raw_bad) {
118	    raw_bad_size(ft);
119	    return 0;
120	  }
121	
122	  while (done < len) {
123	    size_t n = min(len - done, (size_t)RAW_BLOCK), got = 0, i;
124	
125	    switch (kind) {
126	      case raw_s8:
127	        RAW_READ_LOOP(raw_read_bytes(ft, t.b, n),
128	            SOX_SIGNED_8BIT_TO_SAMPLE((int8_t)t.b[i], ft->clips));
129	        break;
130	      case raw_u8:
131	        RAW_READ_LOOP(raw_read_bytes(ft, t.b, n),
132	            SOX_UNSIGNED_8BIT_TO_SAMPLE(t.b[i], ft->clips));
133	        break;
134	      case raw_ulaw:
135	        RAW_READ_LOOP(raw_read_bytes(ft, t.b, n),
136	            lsx_ulaw2linear_table[t.b[i]]);
137	        break;
138	      case raw_alaw:
139	        RAW_READ_LOOP(raw_read_bytes(ft, t.b, n),
140	            lsx_alaw2linear_table[t.b[i]]);
141	        break;
142	      case raw_s16:
143	        RAW_READ_LOOP(lsx_read_w_buf(ft, t.w, n),
144	            SOX_SIGNED_16BIT_TO_SAMPLE((int16_t)t.w[i], ft->clips));
145	        break;
146	      case raw_u16:
147	        RAW_READ_LOOP(lsx_read_w_buf(ft, t.w, n),
148	            SOX_UNSIGNED_16BIT_TO_SAMPLE(t.w[i], ft->clips));
149	        break;
150	      case raw_s24:
151	        RAW_READ_LOOP(lsx_read_3_buf(ft, t.dw, n),
152	            SOX_SIGNED_24BIT_TO_SAMPLE((sox_sample_t)(t.dw[i] << 8) >> 8,
153	                                       ft->clips));
154	        break;
155	      case raw_u24:
156	        RAW_READ_LOOP(lsx_read_3_buf(ft, t.dw, n),
157	            SOX_UNSIGNED_24BIT_TO_SAMPLE(t.dw[i], ft->clips));
158	        break;
159	      case raw_s32:
160	        RAW_READ_LOOP(lsx_read_dw_buf(ft, t.dw, n),
161	            SOX_SIGNED_32BIT_TO_SAMPLE((int32_t)t.dw[i], ft->clips));
162	        break;
163	      case raw_u32:
164	        RAW_READ_LOOP(lsx_read_dw_buf(ft, t.dw, n),
165	            SOX_UNSIGNED_32BIT_TO_SAMPLE(t.dw[i], ft->clips));
166	        break;
167	      case raw_f32:
168	        RAW_READ_LOOP(lsx_read_f_buf(ft, t.f, n),
169	            SOX_FLOAT_32BIT_TO_SAMPLE(t.f[i], ft->clips));
170	        break;
171	      case raw_f64:
172	        RAW_READ_LOOP(lsx_read_df_buf(ft, t.d, n),
173	            SOX_FLOAT_64BIT_TO_SAMPLE(t.d[i], ft->clips));
174	        break;
175	      default:
176	        return done;
177	    }
178	    buf += got;
179	    done += got;
180	    if (got < n)
181	      break;
182	  }
183	  return done;
184	}
185	
186	/*-------------------------------- Writing ---------------------------------*/
187	
188	#define RAW_WRITE_LOOP(conv, write_n) do { \
189	    for (i = 0; i < n; ++i) \
190	      conv; \
191	    put = write_n; \
192	  } while (0)
193	
194	size_t lsx_rawwrite(sox_format_t ft, sox_sample_t const *buf, size_t len)
195	{
196	  raw_kind_t kind = raw_kind(ft);
197	  size_t done = 0;
198	  raw_block_t t;
199	
200	  if (kind == raw_bad) {
201	    raw_bad_size(ft);
202	    return 0;
203	  }
204	
205	  while (done < len) {
206	    size_t n = min(len - done, (size_t)RAW_BLOCK), put = 0, i;
207	
208	    switch (kind) {
209	      case raw_s8:
210	        RAW_WRITE_LOOP(
211	            t.b[i] = (uint8_t)SOX_SAMPLE_TO_SIGNED_8BIT(buf[i], ft->clips),
212	            raw_write_bytes(ft, t.b, n));
213	        break;
214	      case raw_u8:
215	        RAW_WRITE_LOOP(
216	            t.b[i] = SOX_SAMPLE_TO_UNSIGNED_8BIT(buf[i], ft->clips),
217	            raw_write_bytes(ft, t.b, n));
218	        break;
219	      case raw_ulaw:
220	        RAW_WRITE_LOOP(
221	            t.b[i] = lsx_14linear2ulaw(
222	                (int16_t)SOX_SAMPLE_TO_SIGNED(14, buf[i], ft->clips)),
223	            raw_write_bytes(ft, t.b, n));
224	        break;
225	      case raw_alaw:
226	        RAW_WRITE_LOOP(
227	            t.b[i] = lsx_13linear2alaw(
228	                (int16_t)SOX_SAMPLE_TO_SIGNED(13, buf[i], ft->clips)),
229	            raw_write_bytes(ft, t.b, n));
230	        break;
231	      case raw_s16:
232	        RAW_WRITE_LOOP(
233	            t.w[i] = (uint16_t)SOX_SAMPLE_TO_SIGNED_16BIT(buf[i], ft->clips),
234	            lsx_write_w_buf(ft, t.w, n));
235	        break;
236	      case raw_u16:
237	        RAW_WRITE_LOOP(
238	            t.w[i] = SOX_SAMPLE_TO_UNSIGNED_16BIT(buf[i], ft->clips),
239	            lsx_write_w_buf(ft, t.w, n));
240	        break;
241	      case raw_s24:
242	        RAW_WRITE_LOOP(
243	            t.dw[i] = (uint32_t)SOX_SAMPLE_TO_SIGNED_24BIT(buf[i], ft->clips) &
244	                      0xffffffUL,
245	            lsx_write_3_buf(ft, t.dw, n));
246	        break;
247	      case raw_u24:
248	        RAW_WRITE_LOOP(
249	            t.dw[i] = SOX_SAMPLE_TO_UNSIGNED_24BIT(buf[i], ft->clips) &
250	                      0xffffffUL,
251	            lsx_write_3_buf(ft, t.dw, n));
252	        break;
253	      case raw_s32:
254	        RAW_WRITE_LOOP(
255	            t.dw[i] = (uint32_t)SOX_SAMPLE_TO_SIGNED_32BIT(buf[i], ft->clips),
256	            lsx_write_dw_buf(ft, t.dw, n));
257	        break;
258	      case raw_u32:
259	        RAW_WRITE_LOOP(
260	            t.dw[i] = SOX_SAMPLE_TO_UNSIGNED_32BIT(buf[i], ft->clips),
261	            lsx_write_dw_buf(ft, t.dw, n));
262	        break;
263	      case raw_f32:
264	        RAW_WRITE_LOOP(
265	            t.f[i] = SOX_SAMPLE_TO_FLOAT_32BIT(buf[i], ft->clips),
266	            lsx_write_f_buf(ft, t.f, n));
267	        break;
268	      case raw_f64:
269	        RAW_WRITE_LOOP(
270	            t.d[i] = SOX_SAMPLE_TO_FLOAT_64BIT(buf[i], ft->clips),
271	            lsx_write_df_buf(ft, t.d, n));
272	        break;
273	      default:
274	        return done;
275	    }
276	    buf += put;
277	    done += put;
278	    if (put < n)
279	      break;
280	  }
281	  return done;
282	}
