331	int lsx_rawstart(sox_format_t ft, sox_bool default_rate,
332	                 sox_bool default_channels, sox_bool default_length,
333	                 sox_encoding_t encoding, unsigned bits_per_sample)
334	{
335	  if (default_rate && ft->signal.rate == 0) {
336	    raw_warn("`%s': sample rate not specified; trying %gkHz", ft->filename, 8.);
337	    ft->signal.rate = 8000;
338	  }
339	  if (default_channels && ft->signal.channels == 0) {
340	    raw_warn("`%s': # channels not specified; trying mono", ft->filename);
341	    ft->signal.channels = 1;
342	  }
343	  if (encoding != SOX_ENCODING_UNKNOWN) {
344	    if (ft->mode == 'r' && ft->encoding.encoding != SOX_ENCODING_UNKNOWN &&
345	        ft->encoding.encoding != encoding)
346	      raw_report("`%s': Format options overriding file-type encoding",
347	                 ft->filename);
348	    else
349	      ft->encoding.encoding = encoding;
350	  }
351	  if (bits_per_sample != 0) {
352	    if (ft->mode == 'r' && ft->encoding.bits_per_sample != 0 &&
353	        ft->encoding.bits_per_sample != bits_per_sample)
354	      raw_report("`%s': Format options overriding file-type sample-size",
355	                 ft->filename);
356	    else
357	      ft->encoding.bits_per_sample = bits_per_sample;
358	  }
359	  if (ft->mode != 'r')
360	    return lsx_rawstartwrite(ft);
361	  return default_length ? lsx_rawstartread(ft) : SOX_SUCCESS;
362	}
